import {createWorldEstimator,BOOTSTRAP_REPEATS,MIN_CONFIDENCE_WORLDS} from './statistics-estimates.js';
import {weightedSummary} from './weighted-statistics.js';
import {WORLD_SAVE_VERSION,MAX_WORLD_SAVE_BYTES} from './world-save.js';
import {v,p,a,table,details} from './guide-markup.js';

/** Учебные значения проходят тот же оцениватель, что и статистика. */
export function guideWeightsExample(){
 const worlds=[{id:'short',values:[1,2,3]},{id:'long',values:[1,2,3,4,5,6,7,8,9]}];
 return {worlds:createWorldEstimator(worlds,'worlds').center,individuals:createWorldEstimator(worlds,'individuals').center,worldMedians:weightedSummary([2,5]).median};
}
const example=guideWeightsExample();
